import "../css/ProfileInfo.css";
import ProfileImage from "../../assets/images/profile_image_template.png";
import { useState } from "react";
export default function ProfileInfo(props) {
  return (
    <div className="profileInfoContainer">
        <span className="profileInfoHeader">
          <img
              src={ProfileImage}
              alt="Profile"
              className="profileInfoImage"
          />
          {props.userDetails && <h2>{props.userDetails.username}</h2>}
          <i
            className="fa-solid fa-xmark close-icon"
            onClick={() => props.setIsProfileOpen(false)}
          ></i>
        </span>
        <span className="profileInfoDetails">
          <p>Email: {props.userDetails && props.userDetails.usermail}</p>
          <p>Phone: {props.userDetails && props.userDetails.phone}</p>
          <p>Address: {props.userDetails && props.userDetails.address}</p>
        </span>
    </div>
  );
}
